root.render(
  <React.StrictMode>
    <GoogleOAuthProvider clientId="930710046592-nnttnjj8v7mia8oc63t93fnkhcnh0t07.apps.googleusercontent.com">
      <CartProvider>
        <App />
      </CartProvider>
    </GoogleOAuthProvider>
  </React.StrictMode>
);

reportWebVitals();
